"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9731],{72123:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[{"name":"Context","desc":"What a tool gets to work with. Every field is shared by all tools; a tool keeps its own data in\\nits state table, never here.","source":{"line":37,"path":"src/Tools/Types.luau"}},{"name":"Preview","desc":"What one preview draws. Ghost parts, an optional red cut volume, small markers for holes or\\njoins, and a message for the status line.","source":{"line":57,"path":"src/Tools/Types.luau"}},{"name":"Tool","desc":"One tool, or a family of tools sharing code (each mode is its own `Tool` value).","fields":[{"name":"Id","lua_type":"string","desc":"the mode, such as `Room`"},{"name":"Draws","lua_type":"boolean?","desc":"a point-to-point tool: the bar shows Alt and axis-lock hints"},{"name":"Turns","lua_type":"boolean?","desc":"R turns what it places by 90 degrees instead of rotating the selection"},{"name":"Begin","lua_type":"(ctx) -> any","desc":"makes the tool\'s state when it is picked; returns nil to refuse, after saying why"},{"name":"Preview","lua_type":"(ctx, state) -> Preview?","desc":"what to draw now; nil draws nothing"},{"name":"Click","lua_type":"(ctx, state, preview) -> ()","desc":""},{"name":"Release","lua_type":"((ctx, state) -> ())?","desc":"left button up"},{"name":"Confirm","lua_type":"((ctx, state) -> boolean)?","desc":"Enter; true when it did something"},{"name":"Back","lua_type":"((ctx, state) -> string?)?","desc":"Esc; a message when it undid a step, nil to leave the tool"},{"name":"Lock","lua_type":"((ctx, state, axis, plane) -> ())?","desc":"X / Y / Z, with Alt for a plane"},{"name":"Typing","lua_type":"((state) -> NumericInput?)?","desc":"where typed digits go right now, if anywhere"},{"name":"Busy","lua_type":"((state) -> boolean)?","desc":"true while the tool drives the overlay itself, so previews pause"},{"name":"Refresh","lua_type":"((ctx, state) -> ())?","desc":"something the tool reads from outside changed, such as the brush list"},{"name":"Finish","lua_type":"((ctx, state) -> ())?","desc":"the tool is being left; undo anything it shows"}],"source":{"line":85,"path":"src/Tools/Types.luau"}}],"name":"ToolTypes","desc":"The contract every tool follows. A tool is a table of functions plus a state table it makes in\\n`Begin`; the runner (`Tools/Runner`) is the only caller. All of a tool\'s state lives in that\\ntable, so leaving or resetting a tool is just dropping the table, and a bug in one tool cannot\\nleak into another.\\n\\nA frame of a tool\'s life:\\n\\n1. `Preview` runs about twenty times a second. It reads the mouse through `ctx.Cursor` and\\n   returns what to draw. It must not change the place.\\n2. `Click` runs on a left click, right after a fresh `Preview`, which it receives. Changes to\\n   the place go through `ctx.Edit`, so each build is one undo step.\\n3. `Back` runs on Esc. It undoes one step and says what it did, or returns nil to leave the tool.","source":{"line":19,"path":"src/Tools/Types.luau"}}')}}]);